PANELS = [('f', 'flow', '版本与弃用'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("用 autoscaling/v2 创建 HPA(CPU 50% + 内存 70%,scaleDown 稳定窗口 60 秒)。用 v2 读:spec 有 behavior、metrics(2 项:cpu=50%、memory=70%)。同一个对象用 v1 读:spec 只有 targetCPUUtilizationPercentage=50,内存指标和 behavior 被塞进了 autoscaling.alpha.kubernetes.io/metrics、/behavior、/conditions 三个注解,metrics 注解的值是 [{\"type\":\"Resource\",\"resource\":{\"name\":\"memory\",\"targetAverageUtilization\":70}}]。", f=fl(F1, cur=[3], done=[0, 1, 2]), t=tl(S(1), mark=lidx(S(1), 'targetCPUUtilizationPercentage=50', 'autoscaling.alpha.kubernetes.io/metrics ='), done=lidx(S(1), 'v2:apiVersion')), kv=KV([['v2', '完整的字段'], ['v1', '装不下的信息放进 autoscaling.alpha 注解'], ['同一个对象', '只是不同版本的视图']], ['v1'])),
    step("etcd 里存的版本:用 v2 创建的 h1(1334 字节)和用 v1 创建的 h2(1006 字节),值都以 k8s\\x00 开头(protobuf 封装),解出的 apiVersion 都是 autoscaling/v2,kind=HorizontalPodAutoscaler。不管用哪个版本写,存的是存储版本。", f=fl(F1, cur=[1], done=[0]), t=tl(S(2), mark=lidx(S(2), 'h1:etcd', 'h2:etcd')), kv=KV([['写入', '转成存储版本 autoscaling/v2'], ['etcd', '内置资源是 protobuf,不是 JSON'], ['h1 / h2', '1334 / 1006 字节']], ['写入'])),
    step("kubectl get endpoints 在输出末尾打出 Warning: v1 Endpoints is deprecated in v1.33+; use discovery.k8s.io/v1 EndpointSlice,这是响应头 Warning: 299 带回来的;/metrics 里 apiserver_requested_deprecated_apis 是 gauge,endpoints 那一行值为 1。CRD 里给 v1beta1 标了 deprecated: true 和自定义 deprecationWarning,用 v1beta1 读就得到那句警告,用 v1 读没有;metrics 里也多了 things/v1beta1 一行。", f=fl(F3, cur=[1, 2], done=[0], mark=[3]), t=tl(S(3), mark=lidx(S(3), 'Warning:', '响应头里的警告'), done=lidx(S(3), 'gauge', 'resource="endpoints"')), kv=KV([['Warning: 299', '服务端写进响应头,kubectl 显示'], ['apiserver_requested_deprecated_apis', 'gauge,请求过就是 1,不是次数'], ['CRD 的 deprecated', '自己的版本也能发出同样的警告']], ['apiserver_requested_deprecated_apis'])),
    step("发现接口:/apis/autoscaling 的 preferredVersion 是 autoscaling/v2,versions 里 v2 排在 v1 前面;kubectl get hpa 实际请求 /apis/autoscaling/v2/…;写全名 horizontalpodautoscalers.v1.autoscaling 才请求 /apis/autoscaling/v1/…;hpa.v1.autoscaling(短名带版本)仍然请求 v2。", f=fl(F4, cur=[2], mark=[3], done=[0, 1]), t=tl(S(4), mark=lidx(S(4), 'hpa.v1.autoscaling(短名带版本)'), done=lidx(S(4), 'horizontalpodautoscalers.v1.autoscaling 实际')), kv=KV([['preferredVersion', 'kubectl 默认用它'], ['全名.版本.组', '才能指定版本'], ['短名.版本', '版本被忽略']], ['全名.版本.组'])),
]
A = mkartk('k5', 5, 'Kubernetes,API 版本,弃用,autoscaling,Warning,真实验证,动画演示',
    '在 kind 集群里实测同一个 HPA 用 autoscaling/v1 与 v2 读出来的样子:v1 里只有 targetCPUUtilizationPercentage,内存指标和 behavior 被塞进 autoscaling.alpha.kubernetes.io 的注解;etcd 里不管用哪个版本写都存成 autoscaling/v2 的 protobuf;读已弃用的 v1 Endpoints 和 CRD 里标记 deprecated 的版本会得到响应头 Warning: 299,apiserver_requested_deprecated_apis 是值为 1 的 gauge;kubectl get hpa 默认请求 preferredVersion v2,短名加版本时版本被忽略。',
    '同一个 Kubernetes 对象可以用多个 API 版本读写,它们是同一份数据的不同视图。这篇拿 HPA 的 v1 和 v2 对照着读,把 etcd 里存的版本解码出来,再看弃用警告是怎么从服务端传到你终端的,以及 kubectl 到底请求了哪个版本。',
    [('1 → 3', 'v1 视图里比 v2 多出来的 autoscaling.alpha 注解个数(metrics、behavior、conditions)'), ('autoscaling/v2', 'v1 和 v2 两种方式创建的 HPA 在 etcd 里的 apiVersion'), ('Warning: 299', '读弃用 API 时响应头里的警告,kubectl 把它打印在输出末尾')],
    [('一个对象,两种样子', '<p>同一个 HPA,v2 读出来 <code>spec</code> 有 <code>metrics</code>(CPU 50%、内存 70% 两项)和 <code>behavior</code>。v1 的 schema 里只有 <code>targetCPUUtilizationPercentage</code>,装不下的内存指标、behavior 和 conditions 被写进 <code>autoscaling.alpha.kubernetes.io/metrics</code>、<code>/behavior</code>、<code>/conditions</code> 三个注解里,所以旧客户端读到的是个“降级”的视图。用 v1 去改这个对象时要特别小心别把这些注解当普通注解弄丢了。</p>'),
     ('etcd 里存哪个版本', '<p>不管用 v2 还是 v1 创建,etcd 里的值都以 <code>k8s\\x00</code> 开头(内置资源用 protobuf 封装),解出的类型头都是 <code>autoscaling/v2 HorizontalPodAutoscaler</code>。写入时先转成存储版本,读取时再转成请求的版本。注意内置资源在 etcd 里不是 JSON(CRD 才是)。</p>'),
     ('弃用警告怎么传到终端', '<p>读 v1 的 <code>Endpoints</code>,服务端在响应头里加了 <code>Warning: 299 - "v1 Endpoints is deprecated in v1.33+; use discovery.k8s.io/v1 EndpointSlice"</code>,kubectl 把它打印在输出末尾。<code>/metrics</code> 里 <code>apiserver_requested_deprecated_apis</code> 是 gauge:请求过就是 1,不是请求次数,标签里有 <code>removed_release</code>(会被移除的版本,这里为空)。自己的 CRD 也可以给版本标 <code>deprecated: true</code> 并写自定义的 <code>deprecationWarning</code>,用旧版本读就会收到,metrics 里也会多出对应的一行。</p>'),
     ('kubectl 请求哪个版本', '<p><code>/apis/autoscaling</code> 返回 <code>preferredVersion: autoscaling/v2</code>,<code>versions</code> 里 v2 排在前面。<code>kubectl get hpa</code> 请求 <code>/apis/autoscaling/v2/…</code>;想读 v1 要写全名 <code>horizontalpodautoscalers.v1.autoscaling</code>。<code>hpa.v1.autoscaling</code> 这种“短名加版本”的写法版本会被忽略,仍然请求 v2——排查旧版本问题时要用 <code>-v=6</code> 确认请求路径。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);HPA h1 用 kubectl create 以 autoscaling/v2 创建(目标是 replicas=0 的 Deployment,不需要真的有 metrics-server),h2 以 autoscaling/v1 创建;两个版本的内容都用 kubectl get --raw 读出来;etcd 里的值用 etcdctl get -w json 取出 base64 解码,按 protobuf 头解析 apiVersion/kind;弃用警告取自 kubectl -v=8 的响应头;请求路径取自 kubectl -v=6 的日志;弃用的 CRD 版本是自己建的 things.k5.example.com;每种情形各一次',
     '没有验证:真正会被移除的 API(removed_release 不为空的)在本版本 v1.37.0 里没有可请求的;kubectl convert 与 kubent 这类迁移工具;服务端 discovery 的聚合格式(/apis 的 aggregated discovery);API 版本被移除之后存量对象的处理;v1 与 v2 之间所有字段的完整对照'],
    'API 版本与弃用', PANELS)
